const app=document.querySelector('#app'),notice=document.querySelector('#notice');let account
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))
const labels={ready:'可用',preparing:'准备中',failed:'失败',interrupted:'待确认恢复',running:'执行中',queued:'排队中',completed:'已完成',cancelled:'已停止'}
async function api(path,{method='GET',data}={}){const r=await fetch(path,{method,headers:data?{'content-type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const b=await r.json();if(!r.ok){if(r.status===401&&path!=='/auth/login'){location.href='/login';throw new Error('登录已失效')}throw new Error(b.error??'操作失败')}return b}
function toast(text){notice.textContent=text;notice.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>notice.style.display='none',3500)}
async function submit(form,fn){const button=form.querySelector('[type=submit]');const error=form.querySelector('.error');if(button.disabled)return;button.disabled=true;if(error)error.textContent='';try{await fn(Object.fromEntries(new FormData(form)))}catch(e){if(error)error.textContent=e.message;else toast(e.message)}finally{button.disabled=false}}
function modal(title,content,onSubmit){const dialog=document.createElement('dialog');dialog.innerHTML=`<form><h2>${esc(title)}</h2>${content}<div class="error" role="alert"></div><div class="actions"><button type="button" data-close>取消</button><button type="submit" class="primary">确认</button></div></form>`;document.body.append(dialog);dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.querySelector('form').onsubmit=e=>{e.preventDefault();submit(e.currentTarget,async data=>{await onSubmit(data);dialog.close()})};dialog.showModal()}
function shell(page){const admin=account.role==='admin';app.innerHTML=`<div class="shell"><nav class="sidebar" aria-label="主导航"><div class="brand">ChainWeaver</div><a class="nav ${page==='projects'?'active':''}" href="/account">项目与个人空间</a><a class="nav ${page==='executions'?'active':''}" href="/account?tab=executions">执行记录</a><a class="nav ${page==='settings'?'active':''}" href="/account?tab=settings">账号设置</a>${admin?`<a class="nav ${page==='admin'?'active':''}" href="/admin">账号管理</a><a class="nav ${page==='resources'?'active':''}" href="/admin?tab=resources">资源与仓库缓存</a>`:''}<div class="identity"><strong>${esc(account.username)}</strong>${admin?'管理员':'个人账号'}<br><button id="logout">退出登录</button></div></nav><section class="content" id="content"></section></div>`;document.querySelector('#logout').onclick=async()=>{await api('/auth/logout',{method:'POST'});location.href='/login'}}
function heading(title,description,action=''){return `<header class="heading"><div><h1>${title}</h1><p>${description}</p></div>${action}</header>`}
async function login(){app.innerHTML=`<section class="login"><form class="login-box"><div class="brand">ChainWeaver</div><h1>登录你的工作空间</h1><p>继续项目开发与任务执行</p><label for="username">账号</label><input id="username" name="username" autocomplete="username" required autofocus><label for="password">密码</label><input id="password" name="password" type="password" autocomplete="current-password" required><div class="error" role="alert"></div><button type="submit" class="primary">登录</button></form></section>`;document.querySelector('form').onsubmit=e=>{e.preventDefault();submit(e.currentTarget,async data=>{await api('/auth/login',{method:'POST',data});location.href='/account'})}}
async function projects(){shell('projects');const [{projects},runtime]=await Promise.all([api('/platform/projects'),api('/platform/runtime')]);const content=document.querySelector('#content');content.innerHTML=heading('项目与个人空间','项目文件、任务和模型配置仅属于你的账号。','<button class="primary" id="open">进入工作空间</button>')+`<section class="card"><div class="row"><h2>我的项目</h2><button id="new-project">添加项目</button></div>${!projects.length?'<div class="empty">还没有项目。添加 Git 仓库或创建一个空项目开始。</div>':`<div class="grid">${projects.map(p=>`<article class="card"><div class="row"><span class="project-name">${esc(p.name)}</span><span class="badge ${esc(p.status)}">${labels[p.status]??esc(p.status)}</span></div><p class="subtle">${p.repositories.length} 个仓库</p>${p.repositories.map(r=>`<div class="path">${esc(r.url)}</div>`).join('')}${p.error?`<p class="inline-error">${esc(p.error)}</p>`:''}</article>`).join('')}</div>`}</section><p class="help">任务修改代码时会使用独立执行目录；待办任务不会提前占用 worktree。</p>`
  document.querySelector('#open').onclick=async e=>{const b=e.currentTarget;b.disabled=true;b.textContent='正在准备个人空间…';try{await api('/platform/runtime',{method:'POST',data:{resume:true}});location.href='/app/'}catch(err){toast(err.message);b.disabled=false;b.textContent='进入工作空间'}}
  document.querySelector('#new-project').onclick=()=>modal('添加项目',`<label>项目名称<input name="name" required maxlength="100"></label><label>Git 仓库<textarea name="repositories" placeholder="https://github.com/team/frontend.git\nhttps://github.com/team/backend.git"></textarea></label><p class="help">每行一个仓库；多个仓库组成同一个项目。留空可创建空项目。</p><details><summary>工具版本</summary><p class="help">留空时使用仓库版本文件或内置版本。</p><label>Node.js<input name="node" placeholder="24"></label><label>Java<input name="java" placeholder="17"></label><label>Go<input name="go" placeholder="1.23"></label><label>Python<input name="python" placeholder="3.11"></label></details>`,async data=>{const repositories=data.repositories.split('\n').map(s=>s.trim()).filter(Boolean).map((url,i)=>({url,name:url.split('/').at(-1).replace(/\.git$/,'')||`repo-${i+1}`}));const {project}=await api('/platform/projects',{method:'POST',data:{name:data.name,repositories,toolchain:Object.fromEntries(['node','java','go','python'].filter(k=>data[k]).map(k=>[k,data[k]]))}});if(project.status==='failed')toast(project.error);await projects()})
}
async function executions(){shell('executions');const {executions}=await api('/platform/executions');document.querySelector('#content').innerHTML=heading('执行记录','查看排队与执行记录。允许恢复后，在个人空间继续对应会话或任务。')+`<section class="card table-wrap">${executions.length?`<table><thead><tr><th>执行</th><th>状态</th><th>开始时间</th><th>操作</th></tr></thead><tbody>${executions.map(j=>`<tr><td>${esc(j.key)}${j.reason?`<div class="help">${esc(j.reason)}</div>`:''}</td><td><span class="badge ${esc(j.status)}">${labels[j.status]??esc(j.status)}</span></td><td>${esc(j.createdAt)}</td><td>${['interrupted','failed'].includes(j.status)?`<button data-resume="${j.id}">允许恢复</button>`:''}${j.prepared&&!j.acceptedAt&&['completed','failed','interrupted'].includes(j.status)?`<button data-confirm="${j.id}">确认交付</button>`:''}${j.acceptedAt?'<span class="subtle">已确认交付</span>':''}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">还没有执行记录</div>'}</section><p class="help">确认交付满 7 天后，系统仅回收成果可恢复且无待保留修改、无运行占用的执行目录。</p>`;for(const b of document.querySelectorAll('[data-resume]'))b.onclick=async()=>{try{await api(`/platform/executions/${b.dataset.resume}/resume`,{method:'POST',data:{}});await executions()}catch(e){toast(e.message)}};for(const b of document.querySelectorAll('[data-confirm]'))b.onclick=async()=>{await api(`/platform/executions/${b.dataset.confirm}/confirm`,{method:'POST',data:{}});await executions()}}
async function settings(){shell('settings');const c=await api('/platform/credentials');document.querySelector('#content').innerHTML=heading('账号设置','管理自己的登录密码和 Git 身份。')+`<div class="split"><form class="card" id="password-form"><h2>修改密码</h2><label>原密码<input name="oldPassword" type="password" autocomplete="current-password" required></label><label>新密码<input name="password" type="password" minlength="6" maxlength="128" autocomplete="new-password" required></label><div class="error" role="alert"></div><div class="actions"><button type="submit">修改密码</button></div></form><form class="card" id="git-form"><h2>Git 凭据</h2><p class="help">${c.configured?'已配置；已有密钥不会显示。保存将替换现有配置。':'尚未配置。模型凭据在个人工作空间中设置。'}</p><label>Git 服务主机<input name="host" value="${esc(c.host)}" placeholder="github.com" required></label><label>用户名<input name="username" value="${esc(c.username)}" autocomplete="off"></label><label>访问令牌<input name="token" type="password" autocomplete="new-password"></label><details><summary>SSH 密钥</summary><label>私钥<textarea name="sshKey" autocomplete="off"></textarea></label><label>已验证的 known_hosts<textarea name="knownHosts"></textarea></label></details><div class="error" role="alert"></div><div class="actions"><button type="submit">保存 Git 凭据</button></div></form></div>`;document.querySelector('#password-form').onsubmit=e=>{e.preventDefault();submit(e.currentTarget,async data=>{await api('/auth/password',{method:'POST',data});location.href='/login'})};document.querySelector('#git-form').onsubmit=e=>{e.preventDefault();submit(e.currentTarget,async data=>{await api('/platform/credentials',{method:'POST',data});toast('Git 凭据已保存');await settings()})}}
async function admin(){shell('admin');const {accounts}=await api('/platform/admin/accounts');document.querySelector('#content').innerHTML=heading('账号管理','开通账号、停用访问与重置密码。','<button class="primary" id="create-account">创建账号</button>')+`<section class="card table-wrap"><table><thead><tr><th>账号</th><th>角色</th><th>状态</th><th>操作</th></tr></thead><tbody>${accounts.map(a=>`<tr><td>${esc(a.username)}</td><td>${a.role==='admin'?'管理员':'普通用户'}</td><td><span class="badge ${a.disabled?'interrupted':'ready'}">${a.disabled?'已停用':'正常'}</span></td><td><div class="row"><button data-toggle="${a.id}" data-disabled="${a.disabled}">${a.disabled?'重新启用':'停用'}</button><button data-password="${a.id}">重置密码</button></div></td></tr>`).join('')}</tbody></table></section><p class="help">停用会撤销登录、停止执行并保留数据；管理员不能通过此页面进入其他用户空间。</p>`;document.querySelector('#create-account').onclick=()=>modal('创建账号','<label>账号名<input name="username" required minlength="2" maxlength="64" autocomplete="off"></label><label>初始密码<input name="password" type="password" required minlength="6" autocomplete="new-password"></label><label>角色<select name="role"><option value="user">普通用户</option><option value="admin">管理员</option></select></label>',async data=>{await api('/platform/admin/accounts',{method:'POST',data});await admin()});for(const b of document.querySelectorAll('[data-toggle]'))b.onclick=()=>modal(b.dataset.disabled==='true'?'重新启用账号':'停用账号',`<p>${b.dataset.disabled==='true'?'启用后用户需要确认恢复任务。':'该账号的登录会立即失效，正在运行的任务将停止，数据会保留。'}</p>`,async()=>{await api(`/platform/admin/accounts/${b.dataset.toggle}/${b.dataset.disabled==='true'?'enable':'disable'}`,{method:'POST',data:{}});await admin()});for(const b of document.querySelectorAll('[data-password]'))b.onclick=()=>modal('重置密码','<label>新密码<input name="password" type="password" required minlength="6" autocomplete="new-password"></label>',async data=>{await api(`/platform/admin/accounts/${b.dataset.password}/password`,{method:'POST',data});toast('密码已重置，旧登录已失效')})}
async function resources(){shell('resources');const [r,{repositories},{accounts}]=await Promise.all([api('/platform/admin/resources'),api('/platform/admin/repositories'),api('/platform/admin/accounts')]);document.querySelector('#content').innerHTML=heading('资源与仓库缓存','运行资源与共享仓库授权，不展示用户项目或凭据。')+`<div class="metrics"><section class="card"><div class="metric-label">全局执行并发</div><div class="metric">${r.concurrency}</div></section><section class="card"><div class="metric-label">每账号执行并发</div><div class="metric">${r.perUser}</div></section><section class="card"><div class="metric-label">运行中的个人空间</div><div class="metric">${r.runtimes.length} / ${r.limits.maxResident}</div></section></div><section class="card"><h2>运行资源</h2>${r.runtimes.length?`<div class="table-wrap"><table><thead><tr><th>账号</th><th>CPU</th><th>内存</th></tr></thead><tbody>${r.runtimes.map(x=>`<tr><td>${esc(accounts.find(a=>a.id===x.userId)?.username??x.userId)}</td><td>${esc(x.cpu)}</td><td>${esc(x.memory)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="subtle">当前没有运行实例</p>'}</section><section class="card"><div class="row"><h2>允许共享的仓库</h2><button id="authorize">登记仓库</button></div>${repositories.map(x=>`<p>${esc(x.url)}<br><span class="help">${x.users.map(id=>esc(accounts.find(a=>a.id===id)?.username??id)).join('、')}</span></p>`).join('')||'<p class="subtle">尚未登记。私有仓库默认按账号隔离。</p>'}</section>`;document.querySelector('#authorize').onclick=()=>modal('登记共享仓库',`<label>HTTPS Git 地址<input name="url" type="url" required></label><label>允许使用的账号<select name="users" multiple size="5">${accounts.map(a=>`<option value="${a.id}">${esc(a.username)}</option>`).join('')}</select></label><p class="help">仅登记拥有相同代码读取权限的账号，用户仍使用自己的 Git 凭据。</p>`,async data=>{const users=[...document.querySelector('dialog select').selectedOptions].map(o=>o.value);await api('/platform/admin/repositories',{method:'POST',data:{url:data.url,users}});await resources()})}
(async()=>{try{if(location.pathname==='/login')return login();({account}=await api('/auth/me'));const tab=new URL(location.href).searchParams.get('tab');if(location.pathname==='/admin')return tab==='resources'?resources():admin();if(tab==='settings')return settings();if(tab==='executions')return executions();return projects()}catch(e){app.innerHTML=`<section class="login"><div class="card"><h1>暂时无法加载</h1><p>${esc(e.message)}</p><a href="/account">重试</a></div></section>`}})()
